"use strict";
const fs=require("node:fs"),crypto=require("node:crypto"),assert=require("node:assert/strict");
const verifierPath="./tinyrustlm/tools/qwen3-numerical-trace-verifier.js";
const v=require(verifierPath);
const requestPath="artifacts/verification/qwen3-numerical-c1899de-152ec61-20260929-v9-owner-evidence/verification.request.json";
const requestBytes=fs.readFileSync(requestPath),request=JSON.parse(requestBytes);
const f=Math.fround,hash=b=>crypto.createHash("sha256").update(b).digest("hex");
const toBytes=a=>{const b=Buffer.alloc(a.length*4);a.forEach((x,i)=>b.writeFloatLE(f(x),i*4));return b};
const scalarAtol=request.comparison.signFloor;
function exercise(id,arrowId,stageName,reference,candidate,expectedOld,expectedProposed){
  const arrow=request.comparison.arrows.find(a=>a.id===arrowId),t=arrow.thresholds.stages[stageName]||arrow.thresholds.default;
  const stage={stage:stageName,layer:0,elementCount:reference.length,offsetBytes:0};
  const rb=toBytes(reference),cb=toBytes(candidate);
  const m=v.stageMetrics(rb,cb,stage,stage,request.comparison,t);
  const named=["maximumAbsoluteError","maximumRelativeError","maximumNormalizedRmse","minimumCosineSimilarity","maximumSignDisagreementRate","maximumUlp"];
  const oldFailures=named.filter(k=>k==="minimumCosineSimilarity"?m[k]<t[k]:m[k]>t[k]);
  const proposedFailures=oldFailures.filter(k=>k!=="maximumRelativeError"&&k!=="maximumUlp");
  if(arrowId==="reconstructed-to-scalar"){
    if(stageName==="token-embedding"){if(!rb.equals(cb))proposedFailures.push("exact-embedding-identity");}
    else for(let i=0;i<reference.length;i++){const x=rb.readFloatLE(i*4),y=cb.readFloatLE(i*4);if(Math.abs(y-x)>scalarAtol+t.maximumRelativeError*Math.abs(x)){proposedFailures.push("combined-coordinate-error");break;}}
  }
  const argmax=a=>a.reduce((best,_,i)=>a[i]>a[best]?i:best,0);
  if(stageName==="logits"&&arrow.requireGreedyTokenIdentity&&argmax(reference)!==argmax(candidate))proposedFailures.push("greedy-token-identity");
  if(stageName==="logits"&&arrow.requireGreedyTokenIdentity&&argmax(reference)!==argmax(candidate))oldFailures.push("greedy-token-identity");
  assert.equal(oldFailures.length===0,expectedOld,id+" old");
  assert.equal(proposedFailures.length===0,expectedProposed,id+" proposed");
  return {id,arrow:arrowId,stage:stageName,reference:reference.map(f),candidate:candidate.map(f),oldFailures,proposedFailures,metrics:Object.fromEntries(named.map(k=>[k,m[k]]))};
}
const tiny=f(2**-25),ordered=f(f(1+tiny)-1),regrouped=f(f(1-1)+tiny);
assert.equal(ordered,0);assert.equal(regrouped,tiny);
const tests=[];
tests.push(exercise("valid-f32-reduction-reassociation-near-zero","reconstructed-to-scalar","value",[1,regrouped,-1,.5],[1,ordered,-1,.5],false,true));
tests.push(exercise("small-sign-flip-is-not-material-vector-distortion","source-to-reconstructed","feed-forward-normalized",[1,2**-18,-1,.5],[1,-(2**-18),-1,.5],false,true));
tests.push(exercise("material-coordinate-distortion-still-rejected","source-to-reconstructed","feed-forward-normalized",[1,2,-3,4],[1,2,-3,4.5],false,false));
tests.push(exercise("logit-scale-distortion-still-rejected-by-nrmse","source-to-reconstructed","logits",[.1,.2,.3,.4],[.2,.4,.6,.8],false,false));
tests.push(exercise("scalar-material-absolute-error-still-rejected","reconstructed-to-scalar","value",[1,2,-3,4],[1,2,-3,4.03],false,false));
tests.push(exercise("greedy-near-tie-flip-remains-fatal","reconstructed-to-scalar","logits",[1,1-2**-20,-1,-2],[1-2**-20,1,-1,-2],false,false));
tests.push(exercise("embedding-remains-exact","reconstructed-to-scalar","token-embedding",[1,2],[1+2**-23,2],false,false));
let nonfiniteRejected=false;try{const b=toBytes([1,NaN]);v.stageMetrics(b,b,{stage:"value",layer:0,elementCount:2,offsetBytes:0},{stage:"value",layer:0,elementCount:2,offsetBytes:0},request.comparison,request.comparison.arrows[1].thresholds.default)}catch(e){nonfiniteRejected=e.message.includes("numerical-verifier-nonfinite");}assert.equal(nonfiniteRejected,true);
const output={schema:"tinyrustlm.prospective-numerical-metric-synthetic-proof/1",claim:"Synthetic arithmetic only; no model execution or production verifier edit, no historical verdict regrade.",
inputs:{request:{path:requestPath,byteLength:requestBytes.length,sha256:hash(requestBytes)},verifier:{path:verifierPath,sha256:hash(fs.readFileSync(verifierPath))}},
f32Reduction:{operands:[1,tiny,-1],ordered,regrouped,exactRealSum:tiny,absoluteDisagreement:tiny,unitRoundoff:2**-24,condition:"Different valid reduction orders with severe cancellation; ULP distance is not a sound independent equivalence requirement here."},
prospectiveRule:{sourceToQuantized:"Keep existing stage absolute/NRMSE/cosine/sign/top-K guards; relative/ULP remain reported diagnostics for lossy representation. No value changed in those retained guards.",reconstructedToScalar:"Keep existing hard absolute/NRMSE/cosine/sign/top-K/greedy guards plus abs(candidate-reference)<=1e-5+existing-stage-rtol*abs(reference); ULP reported diagnostic; embedding byte-exact.",absoluteNoiseFloorOrigin:"The existing declared signFloor=1e-5, frozen before candidate results; provisional precision-policy choice requiring review, not a theorem that every F32 program is accurate to 1e-5."},
syntheticCases:tests,nonfiniteRejected,passed:tests.length+1,coverageLimit:"Bounded stage-metric and greedy checks; full registered bundle and top-K verification is not executed."};
process.stdout.write(JSON.stringify(output,null,2));
